// Parse incoming Twilio WhatsApp webhook
const body = $input.first().json.body || $input.first().json;

const phoneNumber = body.From || '';
const numMedia = parseInt(body.NumMedia || '0', 10);
const messageText = (body.Body || '').trim();
const mediaUrl = body.MediaUrl0 || '';
const mediaContentType = body.MediaContentType0 || '';
const profileName = body.ProfileName || '';

let routeType = 'unknown';

if (numMedia > 0 && mediaUrl && mediaContentType.startsWith('image/')) {
  routeType = 'image';
} else if (messageText) {
  routeType = 'text_command';
}

return [{
  json: {
    phoneNumber,
    numMedia,
    messageText,
    mediaUrl,
    mediaContentType,
    profileName,
    routeType,
    normalizedPhone: phoneNumber.replace('whatsapp:', ''),
  }
}];

// Evaluate conversation state and determine route
const incoming = $('Parse Incoming Message').first().json;
const stateRows = $input.all().map(item => item.json);

let routeType = incoming.routeType;
let pendingState = null;

const now = Date.now();
const STATE_TTL_MS = 5 * 60 * 1000; // 5 minutes

for (const row of stateRows) {
  if (row.phoneNumber === incoming.phoneNumber && row.pendingAction) {
    const lastInteraction = new Date(row.lastInteraction).getTime();
    if (now - lastInteraction <= STATE_TTL_MS) {
      pendingState = row;
      routeType = 'confirmation';
      break;
    }
  }
}

return [{
  json: {
    ...incoming,
    routeType,
    pendingState,
  }
}];

// Convert downloaded binary image to base64
const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData)[0];
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64 = buffer.toString('base64');
const mediaType = $('Parse Incoming Message').first().json.mediaContentType || 'image/jpeg';

return [{
  json: {
    base64,
    mediaType,
    phoneNumber: $('Parse Incoming Message').first().json.phoneNumber,
    normalizedPhone: $('Parse Incoming Message').first().json.normalizedPhone,
  }
}];

