  json: {
    isValid: !!(validation.isReceipt && validation.isReadable),
    errorMessage,
    phoneNumber,
    base64: $('Convert to Base64').first().json.base64,
    mediaType: $('Convert to Base64').first().json.mediaType,
    normalizedPhone: $('Parse Incoming Message').first().json.normalizedPhone,
