// Process extraction: parse, normalize, categorize, build transaction
const response = $input.first().json;
const text = (response.content && response.content[0] && response.content[0].text) || '';

let extraction;
try {
  const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/) || [null, text];
  const jsonStr = (jsonMatch[1] || text).trim();
  extraction = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('Failed to parse receipt data: ' + e.message);
}

if (extraction.totalAmount == null) {
  throw new Error('Failed to extract total amount from receipt');
}

// Normalize
const VALID_CURRENCIES = ['USD','EUR','GBP','CAD','AUD','JPY','CNY','INR','BRL','MXN','ZAR','KRW','CHF','SEK','NOK','DKK','NZD','SGD','HKD','TWD'];

function normCurrency(code) {
  const upper = (code || '').toUpperCase().trim();
  return VALID_CURRENCIES.includes(upper) ? upper : 'USD';
}

function normDate(d) {
  if (!d) return new Date().toISOString().split('T')[0];
  if (/^\d{4}-\d{2}-\d{2}$/.test(d)) return d;
  const parsed = new Date(d);
  if (!isNaN(parsed.getTime())) return parsed.toISOString().split('T')[0];
  return d;
}

extraction.merchant = extraction.merchant || 'Unknown Merchant';
extraction.date = normDate(extraction.date);
extraction.currency = normCurrency(extraction.currency);
extraction.totalAmount = extraction.totalAmount || 0;
extraction.lineItems = extraction.lineItems || [];
extraction.confidence = extraction.confidence || { overall: 0.5, merchant: 0.5, date: 0.5, total: 0.5, lineItems: 0.5, currency: 0.5 };

// Categorize
const CATEGORIES = [
  { name: 'Food & Dining', kw: ['restaurant','cafe','coffee','pizza','burger','sushi','starbucks','mcdonalds','subway','chipotle','diner','bar','pub','grill','bistro','bakery'] },
  { name: 'Groceries', kw: ['grocery','supermarket','walmart','costco','trader joe','whole foods','kroger','safeway','aldi','target','market','fresh','produce'] },
  { name: 'Transportation', kw: ['gas','fuel','shell','bp','exxon','chevron','uber','lyft','parking','toll','transit','metro','bus'] },
  { name: 'Utilities', kw: ['electric','water','gas bill','internet','comcast','att','verizon','tmobile','utility','power','energy'] },
  { name: 'Entertainment', kw: ['cinema','movie','theater','concert','netflix','spotify','game','arcade','amusement','bowling','museum'] },
  { name: 'Healthcare', kw: ['pharmacy','cvs','walgreens','doctor','dentist','hospital','clinic','medical','health','prescription'] },
  { name: 'Shopping', kw: ['amazon','mall','clothing','shoes','electronics','best buy','nike','zara','h&m','retail'] },
  { name: 'Business', kw: ['office','staples','fedex','ups','printing','copy','business','supplies','coworking'] },
  { name: 'Travel', kw: ['hotel','airbnb','flight','airline','airport','car rental','hertz','marriott','hilton','booking'] },
  { name: 'Education', kw: ['book','course','tuition','school','university','udemy','coursera','library','textbook'] },
  { name: 'Personal Care', kw: ['salon','spa','barber','hair','nail','cosmetics','beauty','skincare','massage'] },
  { name: 'Home & Garden', kw: ['home depot','lowes','ikea','furniture','hardware','garden','plant','home improvement'] },
  { name: 'Gifts & Donations', kw: ['gift','charity','donation','present','flower','card'] },
  { name: 'Subscriptions', kw: ['subscription','membership','gym','club','recurring','monthly'] },
  { name: 'Other', kw: [] }
];

const validCats = new Set(CATEGORIES.map(c => c.name));
let category = 'Other';
if (extraction.category && validCats.has(extraction.category)) {
  category = extraction.category;
} else {
  const searchText = [extraction.merchant, ...extraction.lineItems.map(i => i.description)].join(' ').toLowerCase();
  for (const cat of CATEGORIES) {
    if (cat.name === 'Other') continue;
    if (cat.kw.some(k => searchText.includes(k))) { category = cat.name; break; }
  }
}

// Build transaction
const lineItemsSummary = extraction.lineItems.map(item => {
  const qty = item.quantity > 1 ? ' x' + item.quantity : '';
  return item.description + qty + ' ($' + item.totalPrice.toFixed(2) + ')';
}).join(', ');

function genId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

const phoneNumber = $('Parse Incoming Message').first().json.phoneNumber;
const normalizedPhone = $('Parse Incoming Message').first().json.normalizedPhone;

const transaction = {
  id: genId(),
  timestamp: new Date().toISOString(),
  phoneNumber: normalizedPhone,
  merchant: extraction.merchant,
  date: extraction.date,
  category,
  currency: extraction.currency,
  subtotal: extraction.subtotal ?? '',
  taxAmount: extraction.taxAmount ?? '',
  tipAmount: extraction.tipAmount ?? '',
  totalAmount: extraction.totalAmount,
  paymentMethod: extraction.paymentMethod || '',
  lineItemsSummary,
  confidenceScore: extraction.confidence.overall,
  notes: '',
  monthFormula: '=TEXT(INDIRECT("E"&ROW()),"YYYY-MM")'
};

return [{
  json: {
    transaction,
    extraction,
    phoneNumber,
    normalizedPhone,
  }
}];

// Check for duplicate transactions
const { transaction, extraction, phoneNumber } = $('Process Extraction').first().json;
const rows = $input.all().map(item => item.json);

const normalizedMerchant = transaction.merchant.toLowerCase().trim();
const targetAmount = transaction.totalAmount;
const targetDate = transaction.date;

function isWithinDays(d1, d2, days) {
  const a = new Date(d1 + 'T00:00:00');
  const b = new Date(d2 + 'T00:00:00');
  return Math.abs(a.getTime() - b.getTime()) <= days * 86400000;
}

let isDuplicate = false;
for (const row of rows) {
  const m = (row['Merchant'] || '').toLowerCase().trim();
  const a = parseFloat(row['Total'] || '0');
  const d = row['Receipt Date'] || '';
  if (m === normalizedMerchant && Math.abs(a - targetAmount) < 0.02 && isWithinDays(d, targetDate, 1)) {
    isDuplicate = true;
    break;
  }
}

return [{ json: { isDuplicate, transaction, extraction, phoneNumber } }];

