// Format receipt confirmation message
const { transaction, extraction, phoneNumber } = $('Process Extraction').first().json;

const SYM = { USD:'$', EUR:'\u20ac', GBP:'\u00a3', CAD:'C$', AUD:'A$', JPY:'\u00a5', INR:'\u20b9', BRL:'R$', MXN:'MX$', ZAR:'R', KRW:'\u20a9', CHF:'CHF' };
function fmt(amt, code) {
  const s = SYM[(code||'USD').toUpperCase()] || code || '$';
  const d = ['JPY','KRW'].includes((code||'').toUpperCase()) ? 0 : 2;
  return s + amt.toFixed(d);
}
function fmtDate(iso) {
  const dt = new Date(iso + 'T00:00:00');
  if (isNaN(dt.getTime())) return iso;
  const m = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return m[dt.getMonth()] + ' ' + dt.getDate() + ', ' + dt.getFullYear();
}

const lines = ['*Receipt Recorded!*', ''];
lines.push('Merchant: ' + extraction.merchant);
lines.push('Date: ' + fmtDate(extraction.date));
lines.push('Category: ' + transaction.category);
lines.push('Total: ' + fmt(extraction.totalAmount, extraction.currency));

if (extraction.subtotal != null) {
  lines.push('');
  if (extraction.lineItems && extraction.lineItems.length > 0) {
    lines.push('Items:');
    for (const item of extraction.lineItems) {
      const qty = item.quantity > 1 ? ' x' + item.quantity : '';
      lines.push('- ' + item.description + qty + ': ' + fmt(item.totalPrice, extraction.currency));
    }
    lines.push('');
  }
  lines.push('Subtotal: ' + fmt(extraction.subtotal, extraction.currency));
  if (extraction.taxAmount != null) lines.push('Tax: ' + fmt(extraction.taxAmount, extraction.currency));
  if (extraction.tipAmount != null) lines.push('Tip: ' + fmt(extraction.tipAmount, extraction.currency));
}

if (extraction.paymentMethod) {
  const card = extraction.lastFourDigits ? ' ****' + extraction.lastFourDigits : '';
  lines.push('Payment: ' + extraction.paymentMethod + card);
}

lines.push('');
lines.push('Confidence: ' + Math.round(extraction.confidence.overall * 100) + '%');
if (extraction.confidence.overall < 0.7) {
  lines.push('');
  lines.push('Note: Low confidence (' + Math.round(extraction.confidence.overall * 100) + '%). Please review the details above.');
}
lines.push('');
lines.push('Reply *help* for commands.');

return [{ json: { message: lines.join('\n'), phoneNumber, transaction } }];

// Handle yes/no confirmation responses
const incoming = $input.first().json;
const answer = (incoming.messageText || '').toLowerCase().trim();
const state = incoming.pendingState;

const isYes = ['yes','y','yeah','yep','sure','ok'].includes(answer);

let responseMessage = '';
let action = 'clear_state';
let pendingTransaction = {};

try {
  pendingTransaction = JSON.parse(state.pendingTransactionJson || '{}');
} catch (e) {
  pendingTransaction = {};
}

if (state.pendingAction === 'confirm_duplicate') {
  if (isYes && pendingTransaction.id) {
    action = 'append_duplicate';
    responseMessage = 'Receipt recorded despite duplicate.';
  } else {
    responseMessage = 'Receipt skipped. No duplicate was recorded.';
  }
} else if (state.pendingAction === 'confirm_delete') {
  if (isYes && pendingTransaction.sheetRowNumber) {
    action = 'delete_row';
    responseMessage = 'Transaction deleted successfully.';
  } else {
    responseMessage = 'Delete cancelled.';
  }
} else {
  responseMessage = "I didn't understand that. Send *help* for commands.";
}

return [{ json: { action, responseMessage, pendingTransaction, phoneNumber: incoming.phoneNumber } }];

// Parse text command
const text = $input.first().json.messageText.trim().toLowerCase();
const phoneNumber = $input.first().json.phoneNumber;
const normalizedPhone = $input.first().json.normalizedPhone;

let commandType = 'unknown';
let args = {};

if (text === 'help') commandType = 'help';
else if (text === 'categories') commandType = 'categories';
else if (text === 'budget') commandType = 'budget';
else if (text === 'total') commandType = 'total';
else if (text === 'delete last') commandType = 'delete_last';
else {
  const summaryMatch = text.match(/^summary(?:\s+(\w+))?$/);
  if (summaryMatch) {
    commandType = 'summary';
    const ma = summaryMatch[1];
    if (ma) {
      const MN = {jan:0,january:0,feb:1,february:1,mar:2,march:2,apr:3,april:3,may:4,jun:5,june:5,jul:6,july:6,aug:7,august:7,sep:8,september:8,oct:9,october:9,nov:10,november:10,dec:11,december:11};
      if (ma in MN) { args.month = String(MN[ma]+1).padStart(2,'0'); args.year = String(new Date().getFullYear()); }
    }
  }
  const lastMatch = text.match(/^last\s+(\d+)$/);
  if (lastMatch) { commandType = 'last_n'; args.count = Math.min(parseInt(lastMatch[1],10), 20); }
}

return [{ json: { commandType, args, phoneNumber, normalizedPhone } }];

// Execute data-dependent commands: summary, budget, total, last_n, delete_last
const command = $('Parse Command').first().json;
const { commandType, args, phoneNumber, normalizedPhone } = command;
const allRows = $input.all().map(item => item.json);

const SYM = { USD:'$', EUR:'\u20ac', GBP:'\u00a3', CAD:'C$', AUD:'A$', JPY:'\u00a5', INR:'\u20b9' };
function fmt(a, c) { return (SYM[(c||'USD').toUpperCase()]||c||'$') + a.toFixed(2); }
function fmtD(iso) {
  const d = new Date(iso + 'T00:00:00');
  if (isNaN(d.getTime())) return iso;
  const m = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return m[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
}

let txs = allRows.map((row, idx) => ({
  merchant: row['Merchant'] || '',
  date: row['Receipt Date'] || '',
  category: row['Category'] || 'Other',
  currency: row['Currency'] || 'USD',
  totalAmount: parseFloat(row['Total'] || '0') || 0,
  phoneNumber: (row['Phone Number'] || '').replace('whatsapp:', ''),
  sheetRowNumber: idx + 2,
})).filter(tx => tx.phoneNumber === normalizedPhone);

const BUDGETS = { 'Food & Dining':500, Groceries:600, Transportation:300, Utilities:300, Entertainment:200, Healthcare:200, Shopping:300, Business:500, Travel:500, Education:200, 'Personal Care':150, 'Home & Garden':200, 'Gifts & Donations':100, Subscriptions:100, Other:200 };
const now = new Date();
const curMonth = String(now.getMonth()+1).padStart(2,'0');
const curYear = String(now.getFullYear());
const curPrefix = curYear + '-' + curMonth;
const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];

let responseMessage = '';
let saveDeleteState = false;
let pendingTransaction = null;

if (commandType === 'summary') {
  const month = args.month || curMonth;
  const year = args.year || curYear;
  const prefix = year + '-' + month;
  const mtxs = txs.filter(tx => tx.date.startsWith(prefix));
  const mName = monthNames[parseInt(month,10)-1] || month;
  if (mtxs.length === 0) { responseMessage = 'No transactions found for ' + mName + ' ' + year + '.'; }
  else {
    const total = mtxs.reduce((s,tx) => s+tx.totalAmount, 0);
    const avg = total / mtxs.length;
    const largest = mtxs.reduce((mx,tx) => tx.totalAmount > mx.totalAmount ? tx : mx);
    const catMap = {};
    for (const tx of mtxs) catMap[tx.category] = (catMap[tx.category]||0) + tx.totalAmount;
    const sorted = Object.entries(catMap).sort((a,b) => b[1]-a[1]);
    const lines = ['*'+mName+' '+year+' Summary*','','Total Spent: '+fmt(total,'USD'),'Transactions: '+mtxs.length,'Average: '+fmt(avg,'USD'),'Largest: '+largest.merchant+' ('+fmt(largest.totalAmount,'USD')+')','','*By Category:*'];
    for (const [cat,amt] of sorted) lines.push(cat+': '+fmt(amt,'USD')+' ('+Math.round(amt/total*100)+'%)');
    responseMessage = lines.join('\n');
  }
} else if (commandType === 'budget') {
  const mtxs = txs.filter(tx => tx.date.startsWith(curPrefix));
  const catTotals = {};
  for (const tx of mtxs) catTotals[tx.category] = (catTotals[tx.category]||0) + tx.totalAmount;
  const lines = ['*Budget Status*',''];
  for (const [cat, budget] of Object.entries(BUDGETS)) {
    const spent = catTotals[cat] || 0;
    const pct = budget > 0 ? Math.round(spent/budget*100) : 0;
    const filled = Math.min(Math.round(pct/10), 10);
    const bar = '[' + (pct>100?'!':'#').repeat(filled) + '-'.repeat(10-filled) + ']';
    lines.push(cat, bar+' '+pct+'%'+(pct>100?' OVER':''), fmt(spent,'USD')+' / '+fmt(budget,'USD'), '');
  }
  responseMessage = lines.join('\n');
} else if (commandType === 'total') {
  const mtxs = txs.filter(tx => tx.date.startsWith(curPrefix));
  const total = mtxs.reduce((s,tx) => s+tx.totalAmount, 0);
  responseMessage = 'Total spent in '+monthNames[now.getMonth()]+' '+curYear+': '+fmt(total,'USD');
} else if (commandType === 'last_n') {
  const count = args.count || 5;
  const recent = txs.reverse().slice(0, count);
  if (recent.length === 0) responseMessage = 'No transactions found.';
  else {
    const lines = ['*Last '+recent.length+' Transactions:*',''];
    for (const tx of recent) lines.push(fmtD(tx.date)+' | '+tx.merchant+' | '+fmt(tx.totalAmount,tx.currency)+' | '+tx.category);
    responseMessage = lines.join('\n');
  }
} else if (commandType === 'delete_last') {
  const recent = txs.reverse();
  if (recent.length === 0) responseMessage = 'No transactions found.';
  else {
    const last = recent[0];
    responseMessage = 'Delete this transaction?\n- '+last.merchant+': $'+last.totalAmount.toFixed(2)+'\n\nReply *yes* to confirm or *no* to cancel.';
    saveDeleteState = true;
    pendingTransaction = last;
  }
}

return [{ json: { responseMessage, phoneNumber, saveDeleteState, pendingTransaction } }];
